class Solution {
  public int longestBalanced(String s) {
    int n = s.length();
    char[] c = s.toCharArray();
    int best = 0, run = 0;
    for (int i = 0; i < n; i++) {
      run = i > 0 && c[i] == c[i - 1] ? run + 1 : 1;
      best = Math.max(best, run);
    }
    best = Math.max(best, twoLetters(c, 'a', 'b', 'c'));
    best = Math.max(best, twoLetters(c, 'a', 'c', 'b'));
    best = Math.max(best, twoLetters(c, 'b', 'c', 'a'));
    // all three letters: equal counts means equal prefix differences (a - b, b - c)
    Map<Long, Integer> first = new HashMap<>();
    first.put(key(0, 0, n), 0);
    int a = 0, b = 0, d = 0;
    for (int i = 0; i < n; i++) {
      if (c[i] == 'a') a++;
      else if (c[i] == 'b') b++;
      else d++;
      long k = key(a - b, b - d, n);
      Integer prev = first.putIfAbsent(k, i + 1);
      if (prev != null) best = Math.max(best, i + 1 - prev);
    }
    return best;
  }

  private long key(int x, int y, int n) {
    return (long) (x + n) * (2L * n + 1) + (y + n);
  }

  // longest substring made only of x and y with equal counts (z splits the string into segments)
  private int twoLetters(char[] c, char x, char y, char z) {
    int n = c.length, best = 0, diff = 0, segment = 1;
    int[] stamp = new int[2 * n + 1], firstPos = new int[2 * n + 1];
    stamp[n] = 1;
    firstPos[n] = 0;
    for (int i = 0; i < n; i++) {
      if (c[i] == z) {
        segment++;
        diff = 0;
        stamp[n] = segment;
        firstPos[n] = i + 1;
        continue;
      }
      diff += c[i] == x ? 1 : -1;
      if (stamp[diff + n] == segment) {
        best = Math.max(best, i + 1 - firstPos[diff + n]);
      } else {
        stamp[diff + n] = segment;
        firstPos[diff + n] = i + 1;
      }
    }
    return best;
  }
}
